export const CLOUD_API_MEDIA_HOST_ENV = 'VIRAL_HIT_CLOUD_MEDIA_HOST';

/** Optional host that serves files uploaded to and generated by the Cloud API. */
export const getCloudApiMediaHost = () => {
  const env = (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env;
  const value = env?.[CLOUD_API_MEDIA_HOST_ENV]?.trim().toLowerCase();
  return value && /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(value) ? value : null;
};

const PRIVATE_HOST_SUFFIXES = ['.localhost', '.local', '.internal'];

const isPrivateIpv4 = (hostname: string) => {
  const parts = hostname.split('.').map(Number);
  if (
    parts.length !== 4 ||
    parts.some((part) => !Number.isInteger(part) || part < 0 || part > 255)
  ) {
    return false;
  }
  const [a, b, c] = parts;
  return (
    a === 0 ||
    a === 10 ||
    a === 127 ||
    (a === 100 && b >= 64 && b <= 127) ||
    (a === 169 && b === 254) ||
    (a === 172 && b >= 16 && b <= 31) ||
    (a === 192 && b === 168) ||
    (a === 192 && b === 0 && (c === 0 || c === 2)) ||
    (a === 198 && (b === 18 || b === 19)) ||
    (a === 198 && b === 51 && c === 100) ||
    (a === 203 && b === 0 && c === 113) ||
    a >= 224
  );
};

const isPrivateIpv6 = (hostname: string) => {
  const value = hostname.replace(/^\[|\]$/g, '').toLowerCase();
  return (
    value === '::' ||
    value === '::1' ||
    value.startsWith('::ffff:') ||
    value.startsWith('fc') ||
    value.startsWith('fd') ||
    /^fe[89ab]/.test(value)
  );
};

/**
 * Accept provider-returned public media URLs without coupling integrations to
 * a provider-owned host or path. Literal local/private hosts remain blocked.
 */
export const isPublicHttpMediaUrl = (value: string) => {
  try {
    const url = new URL(value);
    if (
      !['http:', 'https:'].includes(url.protocol) ||
      url.username ||
      url.password
    ) {
      return false;
    }
    const hostname = url.hostname.toLowerCase();
    return !(
      hostname === 'localhost' ||
      PRIVATE_HOST_SUFFIXES.some((suffix) => hostname.endsWith(suffix)) ||
      isPrivateIpv4(hostname) ||
      isPrivateIpv6(hostname)
    );
  } catch {
    return false;
  }
};

export const isCloudApiMediaUrl = (
  value: string,
  host: string | null = getCloudApiMediaHost()
) => {
  if (!host) return false;
  try {
    const url = new URL(value);
    return (
      url.protocol === 'https:' &&
      url.hostname === host &&
      url.port === '' &&
      !url.username &&
      !url.password
    );
  } catch {
    return false;
  }
};

export const isCloudApiInputUrl = (
  value: string,
  host: string | null = getCloudApiMediaHost()
) => {
  if (!isCloudApiMediaUrl(value, host)) return false;
  try {
    return new URL(value).pathname.startsWith('/inputs/');
  } catch {
    return false;
  }
};
